create or replace function public.prepare_accessory_order() returns trigger language plpgsql security definer set search_path='' as $$ declare p record; begin select seller_id,price,currency,stock,status into p from public.accessory_products where id=new.product_id for update; if not found or p.status<>'active' then raise exception 'Product is not available'; end if; if new.quantity<1 or new.quantity>99 or p.stock<new.quantity then raise exception 'Insufficient stock'; end if; new.buyer_id:=(select auth.uid()); if new.buyer_id is null then raise exception 'Authentication required'; end if; new.seller_id:=p.seller_id; new.unit_price:=p.price; new.currency:=p.currency; update public.accessory_products set stock=stock-new.quantity,status=case when stock-new.quantity=0 then 'out_of_stock' else status end where id=new.product_id; return new; end; $$;
create or replace function public.protect_accessory_order_update() returns trigger language plpgsql security definer set search_path='' as $$ begin if new.id is distinct from old.id or new.buyer_id is distinct from old.buyer_id or new.seller_id is distinct from old.seller_id or new.product_id is distinct from old.product_id or new.quantity is distinct from old.quantity or new.unit_price is distinct from old.unit_price or new.currency is distinct from old.currency or new.created_at is distinct from old.created_at then raise exception 'Order identity and pricing fields cannot be changed'; end if; if new.status not in ('pending','accepted','rejected','completed','cancelled') then raise exception 'Invalid order status'; end if; if new.status in ('rejected','cancelled') and old.status not in ('rejected','cancelled') then update public.accessory_products set stock=stock+old.quantity,status=case when status='out_of_stock' then 'active' else status end where id=old.product_id; end if; return new; end; $$;
revoke all on function public.prepare_accessory_order() from public,anon,authenticated;
revoke all on function public.protect_accessory_order_update() from public,anon,authenticated;
drop trigger if exists trg_protect_accessory_order_update on public.accessory_orders;
create trigger trg_protect_accessory_order_update before update on public.accessory_orders for each row execute function public.protect_accessory_order_update();
drop policy if exists accessory_orders_create on public.accessory_orders;
create policy accessory_orders_create on public.accessory_orders for insert to authenticated with check(buyer_id=(select auth.uid()) and quantity between 1 and 99 and exists(select 1 from public.accessory_products p where p.id=product_id and p.status='active' and p.stock>=quantity and p.seller_id<>(select auth.uid())));
drop policy if exists accessory_orders_manage on public.accessory_orders;
create policy accessory_orders_manage on public.accessory_orders for update to authenticated using(seller_id=(select auth.uid()) or public.is_admin()) with check(seller_id=(select auth.uid()) or public.is_admin());